function extract_ipopt_data(inputFile, outputFile)
%EXTRACT_IPOPT_DATA Parse IPOPT log output and export results to CSV
%
%   extract_ipopt_data(INPUTFILE, OUTPUTFILE) reads a text file containing
%   IPOPT optimization logs generated from TROPIC demo runs, extracts key
%   performance and solver statistics for each run, and writes the results
%   to a CSV file.
%
%   Each record in the input file is defined by:
%       Start:  demo: NAME --- run: N
%       End:    demo: LABEL
%
%   ASSUMPTIONS:
%       - Input file follows IPOPT log format as generated by TROPIC demos
%       - Each record contains exactly two "Elapsed time" entries
%       - Field labels match IPOPT output formatting
%
%   EXAMPLE:
%       extract_ipopt_data('log.txt', 'results.csv')
%
%   See also: readlines, regexp, writetable

% Author: Nelson Rosa Jr. (nr@illinoistech.edu)
%         All code generated using M365 Copilot

lines = readlines(inputFile);
results = {};

for i = 1:length(lines)
    line = strtrim(lines(i));

    % --- Start of record ---
    if startsWith(line, "demo:") && contains(line, "--- run:")

        % Reset all fields
        DEMO_NAME=""; NUMBER=NaN; DEMO_LABEL="";
        EXIT=""; OBJ=NaN; ITER=NaN;
        N_f=NaN; N_grad_f=NaN; N_eq=NaN; N_ineq=NaN;
        N_eq_jac=NaN; N_ineq_jac=NaN; N_hess=NaN;
        CONSTR=NaN; CPU_IPOPT=NaN; CPU_NLP=NaN;
        TROPIC_TIME=NaN; TOTAL_TIME=NaN;
        N_VAR=NaN; N_EQ_CONSTR=NaN; N_INEQ_CONSTR=NaN;

        % Extract DEMO_NAME + NUMBER
        t = regexp(line, '^demo:\s*(.*?)\s*--- run:\s*(\d+)', 'tokens');
        if ~isempty(t)
            DEMO_NAME = string(t{1}{1});
            NUMBER    = str2double(t{1}{2});
        end
    end

    % --- End of record (DEMO_LABEL) ---
    if startsWith(line, "demo:") && ~contains(line, "--- run:")
        t = regexp(line, '^demo:\s*(.*)', 'tokens');
        if ~isempty(t)
            DEMO_LABEL = string(t{1}{1});

            % Save record
            results(end+1,:) = {DEMO_LABEL, DEMO_NAME, NUMBER, EXIT, OBJ, ITER, ...
                N_f, N_grad_f, N_eq, N_ineq, N_eq_jac, N_ineq_jac, N_hess, ...
                CONSTR, CPU_IPOPT, CPU_NLP, TROPIC_TIME, TOTAL_TIME, ...
                N_VAR, N_EQ_CONSTR, N_INEQ_CONSTR};
        end
    end

    % ---------- FIELD EXTRACTION ----------

    % Iterations
    t = regexp(line, '^\s*Number of Iterations.*:\s*(\d+)', 'tokens');
    if ~isempty(t), ITER = str2double(t{1}{1}); end

    % Objective (UNSCALED = second value)
    t = regexp(line, '^Objective.*:\s*[0-9.eE+-]+\s+([0-9.eE+-]+)', 'tokens');
    if ~isempty(t), OBJ = str2double(t{1}{1}); end

    % Constraint violation (UNSCALED)
    t = regexp(line, '^Constraint violation.*:\s*[0-9.eE+-]+\s+([0-9.eE+-]+)', 'tokens');
    if ~isempty(t), CONSTR = str2double(t{1}{1}); end

    % EXIT
    t = regexp(line, '^EXIT:\s*(.*)', 'tokens');
    if ~isempty(t), EXIT = string(t{1}{1}); end

    % Function eval counts
    t = regexp(line, 'Number of objective function evaluations\s*=\s*(\d+)', 'tokens');
    if ~isempty(t), N_f = str2double(t{1}{1}); end

    t = regexp(line, 'Number of objective gradient evaluations\s*=\s*(\d+)', 'tokens');
    if ~isempty(t), N_grad_f = str2double(t{1}{1}); end

    t = regexp(line, 'Number of equality constraint evaluations\s*=\s*(\d+)', 'tokens');
    if ~isempty(t), N_eq = str2double(t{1}{1}); end

    t = regexp(line, 'Number of inequality constraint evaluations\s*=\s*(\d+)', 'tokens');
    if ~isempty(t), N_ineq = str2double(t{1}{1}); end

    t = regexp(line, 'Number of equality constraint Jacobian evaluations\s*=\s*(\d+)', 'tokens');
    if ~isempty(t), N_eq_jac = str2double(t{1}{1}); end

    t = regexp(line, 'Number of inequality constraint Jacobian evaluations\s*=\s*(\d+)', 'tokens');
    if ~isempty(t), N_ineq_jac = str2double(t{1}{1}); end

    t = regexp(line, 'Number of Lagrangian Hessian evaluations\s*=\s*(\d+)', 'tokens');
    if ~isempty(t), N_hess = str2double(t{1}{1}); end

    % CPU times
    t = regexp(line, 'Total CPU secs in IPOPT.*=\s*([0-9.eE+-]+)', 'tokens');
    if ~isempty(t), CPU_IPOPT = str2double(t{1}{1}); end

    t = regexp(line, 'Total CPU secs in NLP function evaluations\s*=\s*([0-9.eE+-]+)', 'tokens');
    if ~isempty(t), CPU_NLP = str2double(t{1}{1}); end

    % Elapsed times (capture sequentially)
    t = regexp(line, '^Elapsed time is ([0-9.eE+-]+)', 'tokens');
    if ~isempty(t)
        if isnan(TROPIC_TIME)
            TROPIC_TIME = str2double(t{1}{1});
        else
            TOTAL_TIME = str2double(t{1}{1});
        end
    end

    % Problem size
    t = regexp(line, 'Total number of variables.*:\s*(\d+)', 'tokens');
    if ~isempty(t), N_VAR = str2double(t{1}{1}); end

    t = regexp(line, 'Total number of equality constraints.*:\s*(\d+)', 'tokens');
    if ~isempty(t), N_EQ_CONSTR = str2double(t{1}{1}); end

    t = regexp(line, 'Total number of inequality constraints.*:\s*(\d+)', 'tokens');
    if ~isempty(t), N_INEQ_CONSTR = str2double(t{1}{1}); end

end

% ---------- WRITE TABLE ----------
T = cell2table(results, 'VariableNames', { ...
    'DEMO_LABEL','DEMO_NAME','NUMBER','EXIT','Objective',...
    'Iterations','ObjFuncEvals','ObjGradEvals','EqEvals','IneqEvals',...
    'EqJacEvals','IneqJacEvals','HessEvals','ConstraintViolation',...
    'CPU_IPOPT','CPU_NLP','TROPIC_Elapsed','Elapsed',...
    'NumVariables','NumEqConstraints','NumIneqConstraints'});

writetable(T, outputFile);

end